+func hasStatusCapacity(template client.Object) bool {
+	switch t := template.(type) {
+	case *capiaws.AWSMachineTemplate:
+		return len(t.Status.Capacity) > 0
+	case *capiazure.AzureMachineTemplate:
+		return len(t.Status.Capacity) > 0
+	}
+	return false
+}
